  ('high_risk', 5, 'High risk', 'Heavily stacked, past defaults, lower credit', 'TIB 6+ mo; revenue $25K+/mo; FICO 500+; 2nd position or deeper', 'Malka, Quick Fix, MCHQ (last resort)', 'Many UCC filings from multiple MCA funders; judgments/settled defaults'),
  ('reverse_consolidation', 6, 'Reverse consolidation', 'Merchants with several MCAs and heavy daily payments, still paying', '3+ positions; not bouncing; $50K+ total need; not CA/TX', 'Blue Sky (pending), Malka, TMR (pending)', '3+ MCA UCC filings in the last 12 months'),
  ('term_sba_lendcap', 7, 'Term / SBA (LendCap)', 'Profitable, established, documented businesses', 'TIB 24+ mo; revenue $29K+/mo ($350K+/yr); positive cash flow; tax returns filed', 'LendCap', 'Years in business; property ownership; low or no MCA UCCs; growth signals (hiring, new locations)'),
  ('equipment', 8, 'Equipment', 'Businesses buying specific equipment (gyms, restaurants, medical, construction)', 'Has a vendor quote for specific equipment; decent credit', 'Navitas (A-B); declines -> MCA panel', 'Expansion news, new location openings, equipment-heavy industries')
) as v(key, position, name, who, hard_filters, best_lenders, public_signals)
where w.slug = 'batch-capital'
on conflict (workspace_id, key) do update set
  name = excluded.name, who = excluded.who, hard_filters = excluded.hard_filters,
  best_lenders = excluded.best_lenders, public_signals = excluded.public_signals;
